package com.singtel.promotionservice;
import org.springframework.stereotype.Component;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.transaction.annotation.Transactional;import java.time.Instant;import java.util.*;import com.singtel.platformcommon.Events;import com.fasterxml.jackson.databind.ObjectMapper;
@Component public class LifecycleScheduler {private final PromotionRepository repo;private final Events events;private final ObjectMapper json;public LifecycleScheduler(PromotionRepository r,Events e,ObjectMapper j){repo=r;events=e;json=j;}
@Scheduled(fixedDelay=30000) @Transactional public void tick()throws Exception{Instant now=Instant.now();for(var p:repo.findByStatus(Lifecycle.Status.SCHEDULED)){if(!now.isBefore(p.endAt))continue;if(!now.isBefore(p.startAt))transition(p,Lifecycle.Status.ACTIVE,now);}for(var p:repo.findByStatus(Lifecycle.Status.ACTIVE)){if(!now.isBefore(p.endAt))transition(p,Lifecycle.Status.EXPIRED,now);}}
private void transition(Promotion p,Lifecycle.Status status,Instant now)throws Exception{p.status=status;p.updatedAt=now;List<Object> history=new ArrayList<>(json.readValue(p.historyJson,List.class));history.add(Map.of("status",status,"at",now.toString(),"actor","lifecycle.scheduler"));p.historyJson=json.writeValueAsString(history);repo.save(p);events.append(p.id.toString(),"promotion."+status.name().toLowerCase(),Map.of("promotionId",p.id,"status",status));}}
